/**
 * @suppress
 */
public object FfiConverterTypeFfiOwlivionCore: FfiConverter<FfiOwlivionCore, Pointer> {

    override fun lower(value: FfiOwlivionCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): FfiOwlivionCore {
        return FfiOwlivionCore(value)
    }

    override fun read(buf: ByteBuffer): FfiOwlivionCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: FfiOwlivionCore) = 8UL

    override fun write(value: FfiOwlivionCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



