            FfiConverterOptionalString.read(buf),
            FfiConverterString.read(buf),
        )
    }

    override fun allocationSize(value: FfiSyncStatus) = (
            FfiConverterString.allocationSize(value.`dataType`) +
            FfiConverterInt.allocationSize(value.`version`) +
            FfiConverterOptionalString.allocationSize(value.`lastSyncAt`) +
            FfiConverterString.allocationSize(value.`status`)
    )

    override fun write(value: FfiSyncStatus, buf: ByteBuffer) {
            FfiConverterString.write(value.`dataType`, buf)
            FfiConverterInt.write(value.`version`, buf)
            FfiConverterOptionalString.write(value.`lastSyncAt`, buf)
            FfiConverterString.write(value.`status`, buf)
    }
}





/**
 * FFI-compatible error type.
 * Uses flat_error to convert all variants to string messages on the FFI boundary.
 */
sealed class FfiException(message: String): kotlin.Exception(message) {
        
        class Database(message: String) : FfiException(message)
        
        class Imap(message: String) : FfiException(message)
        
        class Smtp(message: String) : FfiException(message)
        
        class Crypto(message: String) : FfiException(message)
        
        class Sync(message: String) : FfiException(message)
        
        class OAuth(message: String) : FfiException(message)
        
        class Validation(message: String) : FfiException(message)
        
        class NotFound(message: String) : FfiException(message)
        
        class RateLimited(message: String) : FfiException(message)
        
        class Io(message: String) : FfiException(message)
        
        class Other(message: String) : FfiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        
            return when(buf.getInt()) {
            1 -> FfiException.Database(FfiConverterString.read(buf))
            2 -> FfiException.Imap(FfiConverterString.read(buf))
            3 -> FfiException.Smtp(FfiConverterString.read(buf))
            4 -> FfiException.Crypto(FfiConverterString.read(buf))
            5 -> FfiException.Sync(FfiConverterString.read(buf))
            6 -> FfiException.OAuth(FfiConverterString.read(buf))
            7 -> FfiException.Validation(FfiConverterString.read(buf))
            8 -> FfiException.NotFound(FfiConverterString.read(buf))
            9 -> FfiException.RateLimited(FfiConverterString.read(buf))
            10 -> FfiException.Io(FfiConverterString.read(buf))
            11 -> FfiException.Other(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: FfiException): ULong {
        return 4UL
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Database -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.Imap -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.Smtp -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.Crypto -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.Sync -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.OAuth -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.Validation -> {
                buf.putInt(7)
                Unit
            }
            is FfiException.NotFound -> {
                buf.putInt(8)
                Unit
            }
            is FfiException.RateLimited -> {
                buf.putInt(9)
                Unit
            }
            is FfiException.Io -> {
                buf.putInt(10)
                Unit
            }
            is FfiException.Other -> {
                buf.putInt(11)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalLong: FfiConverterRustBuffer<kotlin.Long?> {
    override fun read(buf: ByteBuffer): kotlin.Long? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterLong.read(buf)
    }

    override fun allocationSize(value: kotlin.Long?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterLong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Long?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterLong.write(value, buf)
        }
    }
}




